package main

import (
	"bytes"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const shellStart = "# >>> offline-complete integration >>>"
const shellEnd = "# <<< offline-complete integration <<<"
const shellVersion = "# offline-complete integration v2"

func shellBlock(ocPath string) string {
	return shellStart + "\n" + shellVersion + `
# Generated by oc-manage shell install. Remove with: oc-manage shell uninstall
if [[ -o interactive && -z "$ZSH_EXECUTION_STRING" && $EUID -ne 0 && -z "$SSH_CONNECTION" && -z "$OFFLINE_COMPLETE_ACTIVE" ]]; then
  if [[ -d "$HOME/.local/bin" && ":$PATH:" != *":$HOME/.local/bin:"* ]]; then
    export PATH="$HOME/.local/bin:$PATH"
  fi
  oc_app_pid="$(cat "$HOME/Library/Application Support/offline-complete/app.pid" 2>/dev/null)"
  if [[ -n "$oc_app_pid" ]] && kill -0 "$oc_app_pid" 2>/dev/null; then
    if [[ -x ` + zshQuote(ocPath) + ` ]]; then
      export OFFLINE_COMPLETE_QUIET=1
      export OFFLINE_COMPLETE_AUTO=1
      exec ` + zshQuote(ocPath) + `
    fi
  fi
  unset oc_app_pid
fi
` + shellEnd
}

func zshQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", `'\''`) + "'"
}

func shell(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprintln(stderr, "usage: oc-manage shell status|install|uninstall [--home DIR] [--oc PATH]")
		return 2
	}
	switch args[0] {
	case "status", "install", "uninstall":
	default:
		fmt.Fprintln(stderr, "usage: oc-manage shell status|install|uninstall [--home DIR] [--oc PATH]")
		return 2
	}
	flags := flag.NewFlagSet("shell "+args[0], flag.ContinueOnError)
	flags.SetOutput(stderr)
	home := flags.String("home", "", "home directory")
	ocPath := flags.String("oc", "", "oc executable path")
	if err := flags.Parse(args[1:]); err != nil {
		return 2
	}
	if *home == "" {
		var err error
		*home, err = os.UserHomeDir()
		if err != nil {
			fmt.Fprintf(stderr, "oc-manage: %v\n", err)
			return 1
		}
	}
	if *ocPath == "" {
		system := "/usr/local/bin/oc"
		if info, err := os.Stat(system); err == nil && info.Mode()&0o111 != 0 {
			*ocPath = system
		} else {
			*ocPath = filepath.Join(*home, ".local", "bin", "oc")
		}
	}
	path, installed, err := shellStatus(*home)
	if err != nil {
		fmt.Fprintf(stderr, "oc-manage: %v\n", err)
		return 1
	}
	switch args[0] {
	case "status":
		fmt.Fprintf(stdout, "zshrc: %s\n", path)
		fmt.Fprintf(stdout, "installed: %t\n", installed)
		return 0
	case "install":
		if err := shellInstall(*home, *ocPath); err != nil {
			fmt.Fprintf(stderr, "oc-manage: %v\n", err)
			return 1
		}
		fmt.Fprintf(stdout, "installed shell integration: %s\n", path)
		fmt.Fprintln(stdout, "New interactive zsh windows will start through oc; existing shells are unchanged.")
		kiro := filepath.Join(*home, "Library", "Application Support", "kiro-cli", "shell", "zshrc.pre.zsh")
		if _, err := os.Stat(kiro); err == nil {
			fmt.Fprintln(stdout, "warning: Kiro zsh integration detected; two completion owners can conflict in one shell.")
		}
		return 0
	default:
		if !installed {
			fmt.Fprintf(stdout, "not installed: %s\n", path)
			return 0
		}
		if err := shellUninstall(*home); err != nil {
			fmt.Fprintf(stderr, "oc-manage: %v\n", err)
			return 1
		}
		fmt.Fprintf(stdout, "removed shell integration: %s\n", path)
		return 0
	}
}

func shellStatus(home string) (path string, installed bool, err error) {
	path = filepath.Join(home, ".zshrc")
	target, err := resolveShellFile(path)
	if err != nil {
		return path, false, err
	}
	data, err := os.ReadFile(target)
	if errors.Is(err, os.ErrNotExist) {
		return path, false, nil
	}
	if err != nil {
		return path, false, err
	}
	return path, bytes.Contains(data, []byte(shellStart)), nil
}

func shellInstall(home, ocPath string) error {
	path := filepath.Join(home, ".zshrc")
	target, err := resolveShellFile(path)
	if err != nil {
		return err
	}
	data, err := os.ReadFile(target)
	if errors.Is(err, os.ErrNotExist) {
		data = nil
	} else if err != nil {
		return err
	}
	data = removeShellBlock(data)
	mode := os.FileMode(0o644)
	if info, err := os.Stat(target); err == nil {
		mode = info.Mode().Perm()
	}
	content := shellBlock(ocPath) + "\n\n" + string(data)
	return writeShellFile(target, []byte(content), mode)
}

func shellUninstall(home string) error {
	path := filepath.Join(home, ".zshrc")
	target, err := resolveShellFile(path)
	if err != nil {
		return err
	}
	data, err := os.ReadFile(target)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	remaining := removeShellBlock(data)
	mode := os.FileMode(0o644)
	if info, err := os.Stat(target); err == nil {
		mode = info.Mode().Perm()
	}
	return writeShellFile(target, remaining, mode)
}

func removeShellBlock(data []byte) []byte {
	start := bytes.Index(data, []byte(shellStart))
	end := bytes.Index(data, []byte(shellEnd))
	if start < 0 || end < start {
		return data
	}
	end += len(shellEnd)
	remaining := append([]byte{}, data[:start]...)
	remaining = append(remaining, data[end:]...)
	remaining = bytes.TrimPrefix(remaining, []byte("\n\n"))
	remaining = bytes.TrimPrefix(remaining, []byte("\n"))
	return remaining
}

func resolveShellFile(path string) (string, error) {
	resolved, err := filepath.EvalSymlinks(path)
	if err == nil {
		return resolved, nil
	}
	if errors.Is(err, os.ErrNotExist) {
		return path, nil
	}
	return "", err
}

func writeShellFile(path string, data []byte, mode os.FileMode) error {
	temp, err := os.CreateTemp(filepath.Dir(path), ".zshrc-offline-complete-*")
	if err != nil {
		return err
	}
	name := temp.Name()
	defer os.Remove(name)
	if err := temp.Chmod(mode); err != nil {
		temp.Close()
		return err
	}
	if _, err := temp.Write(data); err != nil {
		temp.Close()
		return err
	}
	if err := temp.Sync(); err != nil {
		temp.Close()
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	return os.Rename(name, path)
}

func shellIntegrationInstalled(home string) bool {
	_, installed, _ := shellStatus(home)
	return installed
}
